/// </summary>
[BusinessEvents(classStr(AAXPurchReturnOrderCreatedBusinessEventContract), 'PurchReturnOrderCreatedBusinessEventName', 'PurchReturnOrderCreatedBusinessEventDescription', ModuleAxapta::PurchaseOrder)]
public final class AAXPurchReturnOrderCreatedBusinessEvent extends BusinessEventsBase
{
    private PurchTable purchTable;

}

