/// <summary>
/// Gets or sets the source PurchTable for building the event contract.
/// </summary>
private PurchTable parmPurchTable(PurchTable _purchTable = purchTable)
{
    purchTable = _purchTable;

    return purchTable;
}

/// <summary>
/// Creates a new <c>AAXPurchReturnOrderCreatedBusinessEvent</c> instance from the specified <c>PurchTable</c> record.
/// </summary>
/// <param name="_purchTable">The source PurchTable record.</param>
/// <returns>A new instance of <c>AAXPurchReturnOrderCreatedBusinessEvent</c>.</returns>
public static AAXPurchReturnOrderCreatedBusinessEvent newFromPurchTable(PurchTable _purchTable)
{
    AAXPurchReturnOrderCreatedBusinessEvent businessEvent = new AAXPurchReturnOrderCreatedBusinessEvent();
    businessEvent.parmPurchTable(_purchTable);

    return businessEvent;
}

/// <summary>
/// Private constructor. Use static factory methods to create instances.
/// </summary>
private void new()
{
}

/// <summary>
/// Builds the data contract for this business event.
/// </summary>
/// <returns>The populated <c>AAXPurchReturnOrderCreatedBusinessEventContract</c>.</returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return AAXPurchReturnOrderCreatedBusinessEventContract::newFromPurchTable(purchTable);
}
